<script setup>
import { ref, computed, watch, onMounted, onBeforeUnmount } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { api } from '@finns/lib/api'
import AdminLayout from '../components/AdminLayout.vue'
import AdminDialog from '../components/AdminDialog.vue'
import PageNav from '../components/PageNav.vue'
const route = useRoute(), router = useRouter(), data = ref(null), loading = ref(true), error = ref(''), message = ref(''), q = ref(''), status = ref(''), level = ref(''), tag = ref(''), editing = ref(null), deleting = ref(null), importing = ref(null), picks = ref([]), busy = ref(false), saveError = ref('')
const levelText = { HIGH: '高', MEDIUM: '中', LOW: '低' }
const levelClass = { HIGH: 'danger', MEDIUM: 'amber', LOW: 'neutral' }
const levelHint = { HIGH: '自动不通过，并转人工复核', MEDIUM: '直接送审，通过才发布', LOW: '放行并留痕，不拦截' }
let request = 0
async function load() {
  const id = ++request; loading.value = true; error.value = ''; q.value = String(route.query.q || ''); status.value = String(route.query.status || ''); level.value = String(route.query.level || ''); tag.value = String(route.query.tag || '')
  try { const result = await api('/api/review/rules?' + new URLSearchParams(route.query)); if (id === request) data.value = result }
  catch (e) { if (id === request) error.value = e.message } finally { if (id === request) loading.value = false }
}
function search() { const query = { ...(q.value.trim() ? { q: q.value.trim() } : {}), ...(status.value ? { status: status.value } : {}), ...(level.value ? { level: level.value } : {}), ...(tag.value ? { tag: tag.value } : {}) }; if (JSON.stringify(query) === JSON.stringify(route.query)) load(); else router.push({ query }) }
function reset() { q.value = ''; status.value = ''; level.value = ''; tag.value = ''; if (!Object.keys(route.query).length) load(); else router.push({ query: {} }) }
function edit(rule) { editing.value = { id: rule?.id, phrase: rule?.phrase || '', note: rule?.note || '', enabled: rule?.enabled !== false, level: rule?.level || 'MEDIUM', expectedVersion: rule?.version || 1 }; saveError.value = '' }
const remove = rule => { deleting.value = { ...rule }; saveError.value = '' }
async function save() { busy.value = true; saveError.value = ''; try { const result = await api('/api/review/rules', { method: 'POST', body: JSON.stringify(editing.value) }); message.value = result.message; editing.value = null; await load() } catch (e) { saveError.value = e.message } finally { busy.value = false } }
async function toggle(rule) { busy.value = true; error.value = ''; try { await api('/api/review/rules', { method: 'POST', body: JSON.stringify({ ...rule, enabled: !rule.enabled, expectedVersion: rule.version }) }); message.value = '规则已' + (rule.enabled ? '停用' : '启用') + '，仅影响后续提交。'; await load() } catch (e) { error.value = e.message } finally { busy.value = false } }
async function confirmDelete() { busy.value = true; saveError.value = ''; try { const result = await api('/api/review/rules/' + deleting.value.id, { method: 'DELETE', body: JSON.stringify({ expectedVersion: deleting.value.version }) }); message.value = result.message; deleting.value = null; await load() } catch (e) { saveError.value = e.message } finally { busy.value = false } }
const importQuery = ref(''), importTag = ref(''), includeSuspect = ref(false), groupSetup = ref([])
const importShown = computed(() => (importing.value?.items || []).filter(i => (!importTag.value || i.tag === importTag.value) && (!importQuery.value.trim() || i.phrase.toLowerCase().includes(importQuery.value.trim().toLowerCase()) || i.tag.includes(importQuery.value.trim()))))
const importCount = computed(() => groupSetup.value.filter(g => g.on).reduce((n, g) => n + (importing.value.items.filter(i => i.tag === g.tag && !i.duplicate && (includeSuspect.value || !i.suspect)).length), 0))
async function openImport() { busy.value = true; saveError.value = ''; try { importing.value = await api('/api/review/rules/import-preview'); importQuery.value = ''; importTag.value = ''; includeSuspect.value = false; groupSetup.value = importing.value.groups.map(g => ({ tag: g.tag, level: g.level, enabled: false, on: g.tag !== '政治' ? true : true })) } catch (e) { error.value = e.message } finally { busy.value = false } }
async function commitImport() { busy.value = true; saveError.value = ''; try { const result = await api('/api/review/rules/import', { method: 'POST', body: JSON.stringify({ groups: groupSetup.value.filter(g => g.on).map(g => ({ tag: g.tag, level: g.level, enabled: g.enabled })), includeSuspect: includeSuspect.value }) }); message.value = result.message; importing.value = null; await load() } catch (e) { saveError.value = e.message } finally { busy.value = false } }
async function batch(tagName, enabled) { busy.value = true; error.value = ''; try { const result = await api('/api/review/rules/batch', { method: 'POST', body: JSON.stringify({ tag: tagName, enabled }) }); message.value = result.message; await load() } catch (e) { error.value = e.message } finally { busy.value = false } }
watch(() => route.fullPath, load)
onMounted(() => { load(); window.addEventListener('finns-review-scene', load) })
onBeforeUnmount(() => window.removeEventListener('finns-review-scene', load))
</script>
<template>
  <AdminLayout title="敏感规则" description="维护发布检测使用的词语、等级与启用状态；一次提交命中多条时取最高等级。" kicker="CONTENT · SENSITIVE RULES" version="FINNS-17 · R3">
    <div class="sr-summary"><span>启用 <strong>{{ data?.enabledCount ?? '—' }}</strong> 条</span><span>停用 <strong>{{ data?.disabledCount ?? '—' }}</strong> 条</span><p>仅站长可管理；变更不回扫历史发布内容。</p></div>
    <div class="sr3-levels" role="group" aria-label="三级处理规则"><div v-for="key in ['HIGH', 'MEDIUM', 'LOW']" :key="key" :class="'sr3-level ' + key"><span class="rv-badge" :class="levelClass[key]">{{ levelText[key] }}敏感</span><strong>{{ data?.levels?.[key] ?? '—' }}</strong><small>{{ levelHint[key] }}</small></div></div>
    <form class="rv-filters sr-toolbar" @submit.prevent="search"><label class="rv-search">搜索规则<input v-model="q" placeholder="输入词语、短语或备注" /></label>
      <label>等级<select v-model="level"><option value="">全部等级</option><option value="HIGH">高</option><option value="MEDIUM">中</option><option value="LOW">低</option></select></label>
      <label v-if="data?.tags?.length">标签<select v-model="tag"><option value="">全部标签</option><option v-for="t in data.tags" :key="t.tag" :value="t.tag">{{ t.tag }}（{{ t.total }}）</option></select></label>
      <label>规则状态<select v-model="status"><option value="">全部状态</option><option value="ENABLED">已启用</option><option value="DISABLED">已停用</option></select></label>
      <button class="btn btn-primary" type="submit">查询</button><button class="btn btn-ghost" type="button" @click="reset">重置</button><button class="btn btn-ghost sr-add" type="button" :disabled="busy" @click="openImport">导入词库…</button><button class="btn btn-primary" type="button" @click="edit()">＋ 新增规则</button></form>
    <div v-if="data?.tags?.length" class="sr3-batch" role="group" aria-label="按标签批量启停"><strong>按标签批量启停</strong><span v-for="t in data.tags" :key="t.tag" class="sr3-batch-item"><b>{{ t.tag }}</b> 启用 {{ t.enabled }} / {{ t.total }}<button :disabled="busy || t.enabled === t.total" @click="batch(t.tag, true)">全部启用</button><button :disabled="busy || !t.enabled" @click="batch(t.tag, false)">全部停用</button></span></div>
    <p v-if="message" class="rv-notice success" role="status">{{ message }}</p>
    <div v-if="loading" class="rv-empty"><h2>正在读取规则</h2></div>
    <div v-else-if="error" class="rv-empty" role="alert"><h2>暂时无法读取</h2><p>{{ error }}</p><button class="btn btn-primary" @click="load">重试</button></div>
    <template v-else><div class="sr-table-caption"><h2>规则列表</h2><span>共 {{ data?.total || 0 }} 条符合条件的规则</span></div>
      <div v-if="!data?.items.length" class="rv-empty"><h2>没有符合条件的规则</h2><p>{{ q || status || level ? '调整搜索词或筛选后再试。' : '可以新增第一条规则；未配置检测时新内容不会直接发布。' }}</p><button class="btn btn-ghost" @click="reset">清空筛选</button></div>
      <table v-else class="sr-table sr3-table"><caption class="sr-only">敏感规则列表，可编辑、启停和删除</caption><thead><tr><th>词语或短语</th><th>等级</th><th>状态</th><th>备注</th><th>操作</th></tr></thead>
        <tbody><tr v-for="rule in data.items" :key="rule.id"><td class="sr-phrase"><strong>{{ rule.phrase }}</strong><small v-if="rule.updatedAt">更新于 {{ new Date(rule.updatedAt).toLocaleDateString('zh-CN') }}</small></td><td data-label="等级"><span class="rv-badge" :class="levelClass[rule.level]">{{ levelText[rule.level] }}</span></td><td data-label="状态"><span class="rv-badge" :class="rule.enabled ? 'green' : 'neutral'">{{ rule.enabled ? '已启用' : '已停用' }}</span></td><td class="sr-note" data-label="备注">{{ rule.note || '—' }}</td><td class="sr-actions"><button :disabled="busy" @click="edit(rule)">编辑</button><button :disabled="busy" @click="toggle(rule)">{{ rule.enabled ? '停用' : '启用' }}</button><button class="danger" :disabled="busy" @click="remove(rule)">删除</button></td></tr></tbody></table>
      <PageNav v-if="data?.total" :page="data.page" :size="data.size" :total="data.total" @go="n => router.push({ query: { ...route.query, page: n } })" /></template>
    <p class="rv-footnote">匹配前统一全半角、大小写，并去掉空白、标点和零宽字符；不识别同义词、谐音、拼音，也不看图片。整词模式、中文单字规则的误伤见示例词库文档。包含的是中性演示词，不是真实敏感词库。</p>
    <details v-if="data?.history.length" class="rv-history"><summary>规则操作记录（{{ data.history.length }}）</summary><p v-for="(entry, i) in data.history" :key="i"><strong>{{ entry.action }} · {{ entry.phrase }}</strong><small>{{ entry.operator }} · {{ new Date(entry.at).toLocaleString('zh-CN') }}</small></p></details>
    <AdminDialog v-if="editing" labelledby="sr-edit-title" context="FINNS · 敏感规则" :busy="busy" @close="editing = null"><span class="kicker">SENSITIVE RULE</span><h2 id="sr-edit-title">{{ editing.id ? '编辑敏感规则' : '新增敏感规则' }}</h2>
      <form @submit.prevent="save"><label class="rv-field">词语或短语<input v-model="editing.phrase" required maxlength="40" placeholder="输入需要匹配的文字" /></label>
        <fieldset class="sr3-level-pick"><legend>敏感等级</legend><label v-for="key in ['LOW', 'MEDIUM', 'HIGH']" :key="key" :class="{ on: editing.level === key }"><input v-model="editing.level" type="radio" name="level" :value="key" /><span class="rv-badge" :class="levelClass[key]">{{ levelText[key] }}</span><small>{{ levelHint[key] }}</small></label></fieldset>
        <label class="rv-field">备注<textarea v-model="editing.note" rows="3" maxlength="200" placeholder="说明用途，便于日后维护" /></label><label class="rv-check"><input v-model="editing.enabled" type="checkbox" />启用此规则</label>
        <p class="rv-notice">保存后仅影响后续提交，不自动下架已有内容。</p><p v-if="saveError" class="rv-notice danger" role="alert">{{ saveError }}</p><div class="rv-dialog-actions"><button class="btn btn-ghost" type="button" :disabled="busy" @click="editing = null">取消</button><button class="btn btn-primary" :disabled="busy">{{ busy ? '保存中…' : '保存规则' }}</button></div></form></AdminDialog>
    <AdminDialog v-if="deleting" labelledby="sr-delete-title" context="FINNS · 删除规则" :busy="busy" @close="deleting = null"><span class="kicker">DELETE RULE</span><h2 id="sr-delete-title">删除这条规则？</h2><p class="sr-delete-phrase">{{ deleting.phrase }}</p><p>删除后，该规则会从列表移除，不再参与后续发布检测。已有发布内容保持不变，操作记录会保留。</p><p v-if="saveError" class="rv-notice danger" role="alert">{{ saveError }}</p><div class="rv-dialog-actions"><button class="btn btn-ghost" :disabled="busy" @click="deleting = null">取消</button><button class="btn btn-primary" :disabled="busy" @click="confirmDelete">{{ busy ? '删除中…' : '确认删除' }}</button></div></AdminDialog>
    <AdminDialog v-if="importing" wide labelledby="sr-import-title" context="FINNS · 导入词库" :busy="busy" @close="importing = null"><span class="kicker">IMPORT PREVIEW · 模拟</span><h2 id="sr-import-title">按标签批量导入候选词库</h2>
      <p class="rv-notice amber">以下是<strong>模拟的样例预览</strong>：原型没有下载任何真实词库文件。来源页面于 {{ importing.source.readAt }} 读取，许可：{{ importing.source.license }}。{{ importing.source.claim }}。</p>
      <ul class="sr3-import-rules"><li v-for="line in importing.rules" :key="line">{{ line }}</li></ul>
      <table class="sr-table sr3-groups"><caption class="sr-only">按标签设置导入方式</caption><thead><tr><th>导入</th><th>标签</th><th>词数</th><th>建议等级</th><th>导入后</th></tr></thead><tbody><tr v-for="g in groupSetup" :key="g.tag"><td><input type="checkbox" v-model="g.on" :aria-label="'导入标签 ' + g.tag" /></td><td><strong>{{ g.tag }}</strong><small v-if="importing.groups.find(x => x.tag === g.tag).suspect"> · 含 {{ importing.groups.find(x => x.tag === g.tag).suspect }} 个疑似误报</small></td><td>{{ importing.groups.find(x => x.tag === g.tag).count }}</td><td><select v-model="g.level" :aria-label="g.tag + ' 的等级'"><option value="HIGH">高</option><option value="MEDIUM">中</option><option value="LOW">低</option></select></td><td><select v-model="g.enabled" :aria-label="g.tag + ' 导入后状态'"><option :value="false">停用（稍后批量启用）</option><option :value="true">立即启用</option></select></td></tr></tbody></table>
      <label class="rv-check"><input type="checkbox" v-model="includeSuspect" />包含疑似误报词（默认不导入，启用后可能误伤正常内容）</label>
      <div class="sr3-import-search"><h3>样例检索（仅查询）</h3><form class="rv-filters" @submit.prevent><label class="rv-search">搜索词语或标签<input v-model="importQuery" placeholder="例如：微信、诈骗" /></label><label>标签<select v-model="importTag"><option value="">全部</option><option v-for="g in importing.groups" :key="g.tag" :value="g.tag">{{ g.tag }}</option></select></label></form>
        <table class="sr-table sr3-import"><thead><tr><th>词语</th><th>标签</th><th>提示</th></tr></thead><tbody><tr v-for="item in importShown" :key="item.phrase" :class="{ suspect: item.suspect }"><td><strong>{{ item.phrase }}</strong></td><td>{{ item.tag }}</td><td><span v-if="item.duplicate" class="rv-badge neutral">已存在</span><span v-else-if="item.suspect" class="rv-badge amber">疑似误报 · {{ item.why }}</span><span v-else class="rv-badge green">可用</span></td></tr><tr v-if="!importShown.length"><td colspan="3">没有符合条件的样例词。</td></tr></tbody></table></div>
      <p v-if="saveError" class="rv-notice danger" role="alert">{{ saveError }}</p><div class="rv-dialog-actions"><button class="btn btn-ghost" :disabled="busy" @click="importing = null">取消</button><button class="btn btn-primary" :disabled="busy || !importCount" @click="commitImport">{{ busy ? '导入中…' : `按设置导入 ${importCount} 条` }}</button></div></AdminDialog>
  </AdminLayout>
</template>
